using System.Collections.Concurrent;using AfriWallet.Fraud.DeviceRisk.Application.Abstractions;namespace AfriWallet.Fraud.DeviceRisk.Infrastructure;public sealed class InMemoryDeviceRiskAuditStore:IDeviceRiskAuditStore{private readonly ConcurrentQueue<DeviceRiskAuditEvent> _events=new();public Task AppendAsync(DeviceRiskAuditEvent e,CancellationToken ct=default){ct.ThrowIfCancellationRequested();_events.Enqueue(e);return Task.CompletedTask;}public Task<IReadOnlyCollection<DeviceRiskAuditEvent>> GetByProfileAsync(Guid id,CancellationToken ct=default){ct.ThrowIfCancellationRequested();IReadOnlyCollection<DeviceRiskAuditEvent> result=_events.Where(x=>x.RiskProfileId==id).ToArray();return Task.FromResult(result);}}